const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const somalia = ee.Geometry.Polygon([
    [40.981, 11.987], [51.412, 11.987], [51.412, -1.659], [40.981, -1.659], [40.981, 11.987]
  ]);

  const april2019 = ['2019-04-01', '2019-04-30'];
  const baselineStart = '2015-04-01';
  const baselineEnd = '2020-04-30';

  // 2. Data Acquisition - SMAP Soil Moisture
  const smapCollection = ee.ImageCollection('NASA/SMAP/SPL4SMGP/007')
    .select('sm_surface');

  // April 2019 data
  const april2019Col = smapCollection.filterDate(april2019[0], april2019[1]);

  // Baseline data (all Aprils 2015-2020 excluding 2019)
  const baselineCol = smapCollection
    .filterDate(baselineStart, baselineEnd)
    .filter(ee.Filter.calendarRange(4, 4, 'month'))
    .filter(ee.Filter.neq('year', 2019));

  // Check collection sizes
  const april2019Size = april2019Col.size().getInfo();
  const baselineSize = baselineCol.size().getInfo();

  console.log(`April 2019 Images: ${april2019Size}`);
  console.log(`Baseline April Images: ${baselineSize}`);

  if (april2019Size === 0 || baselineSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean soil moisture
  const april2019Mean = april2019Col.mean();
  const baselineMean = baselineCol.mean();

  // Check pixel counts
  const april2019Count = april2019Mean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: somalia,
    scale: 9000,
    maxPixels: 1e9
  }).get('sm_surface').getInfo();

  const baselineCount = baselineMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: somalia,
    scale: 9000,
    maxPixels: 1e9
  }).get('sm_surface').getInfo();

  console.log(`April 2019 Valid Pixels: ${april2019Count}`);
  console.log(`Baseline Valid Pixels: ${baselineCount}`);

  if (april2019Count === 0 || baselineCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean soil moisture values
  const april2019Val = april2019Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: somalia,
    scale: 9000,
    maxPixels: 1e9
  }).get('sm_surface').getInfo();

  const baselineVal = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: somalia,
    scale: 9000,
    maxPixels: 1e9
  }).get('sm_surface').getInfo();

  console.log(`April 2019 Soil Moisture: ${april2019Val?.toFixed(4)}`);
  console.log(`Baseline Soil Moisture: ${baselineVal?.toFixed(4)}`);

  // 5. Validation & Final Answer
  if (april2019Val === null || baselineVal === null || 
      isNaN(april2019Val) || isNaN(baselineVal) ||
      april2019Val < 0 || baselineVal < 0) {
    console.log("<answer>C3</answer>");
  } else if (april2019Val < baselineVal) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
